import React from 'react';
import ProfessorDetails from "../components/Professor/ProfessorDetails";
import Navbar from "../components/Homepage/Header/Navbar";

function Professor(props) {
    const {professor, professorList, onChangeProfessor} = props;

    return (

            <div>
                <ProfessorDetails professorList={professorList} onChangeProfessor={onChangeProfessor} isHone={true} professor={professor}/>
                {professor.name}
            </div>
    );
}

export default Professor;
